def investigate(context, acquire):
    receipts = acquire("history")
    # Family: put mode in {ignore, replace, upsert}; channel in {changes, total, total_both};
    # instrumentation in {none, trigger}.
    # We simulate each candidate and keep those consistent with all receipts.

    def simulate(mode, chan, trig, actions):
        # state: dict key->value committed; open transaction per connection
        committed = {}
        # pending writes per connection: list of (key, value) applied at commit
        pending = {"main": None, "other": None}
        # counters
        changes_main = 0
        total_main = 0
        total_other = 0
        # trigger log count (not read, but affects nothing observable except via counters? no)
        # We track last direct row-change count for changes() semantics.
        # changes() returns rows changed by last statement on that connection.
        # total_changes accumulates all row changes on that connection.
        # For trigger: AFTER INSERT trigger inserts one row into log.
        # That trigger's insert counts toward total_changes but NOT changes().
        # Actually in SQLite, changes() returns rows modified by most recent statement,
        # excluding trigger side effects. total_changes includes trigger changes.

        def apply_put(conn, key, value):
            nonlocal changes_main, total_main, total_other
            # determine effect on committed/pending
            # For simplicity, we apply to a working dict representing the connection's view.
            # But transactions complicate. We'll model: each connection has its own view
            # of the database (uncommitted changes visible only to that connection).
            # Since only one transaction at a time, and other connection can write after commit/rollback.
            # We'll maintain committed dict and per-connection pending dict.
            pass

        # Simpler: process sequentially, maintaining committed state and per-connection
        # uncommitted state. Since transactions cannot nest and only one open at a time,
        # we can model: when a transaction is open on conn C, writes on C go to pending[C].
        # Writes on other connection D: if C has open transaction, D can still write?
        # Documentation: "While a transaction is open, writes and transaction actions use that connection;
        # the other connection can write after commit or rollback." So other connection cannot write
        # while transaction open. We'll assume actions are valid.

        # We'll maintain:
        # committed: dict
        # pending: dict or None for each connection
        # For a put on conn:
        #   if pending[conn] is not None: apply to pending[conn]
        #   else: apply to committed directly (autocommit)
        # For begin: pending[conn] = dict(committed)  # snapshot
        # For commit: committed = pending[conn]; pending[conn] = None
        # For rollback: pending[conn] = None

        # But we need to compute row changes for each put.
        # For INSERT OR IGNORE: if key exists, 0 changes; else 1 change.
        # For INSERT OR REPLACE: always 1 change (delete+insert counts as 1? Actually REPLACE deletes existing row then inserts, changes() returns 1).
        # For UPSERT (ON CONFLICT DO UPDATE): if key exists, 1 change (update); else 1 change (insert).
        # So changes per put: ignore -> 0 if exists else 1; replace -> 1; upsert -> 1.

        # Trigger: AFTER INSERT trigger inserts one row into log.
        # This adds 1 to total_changes but not changes().
        # For REPLACE, the insert part triggers the trigger? Yes, AFTER INSERT fires on the new row.
        # For UPSERT, if it's an update, no INSERT trigger fires. If insert, trigger fires.
        # For IGNORE, if ignored, no insert, no trigger.

        # We need to track whether an insert actually happened (for trigger).
        # For REPLACE: always an insert (after delete).
        # For UPSERT: insert if key didn't exist, update if existed.
        # For IGNORE: insert if key didn't exist.

        # Let's implement.

        committed = {}
        pending = {"main": None, "other": None}
        changes_main = 0
        total_main = 0
        total_other = 0

        def get_view(conn):
            if pending[conn] is not None:
                return pending[conn]
            return committed

        def set_view(conn, d):
            if pending[conn] is not None:
                pending[conn] = d
            else:
                committed.clear()
                committed.update(d)

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                pending[conn] = dict(committed)
            elif op == "commit":
                if pending[conn] is not None:
                    committed.clear()
                    committed.update(pending[conn])
                    pending[conn] = None
            elif op == "rollback":
                pending[conn] = None
            elif op == "put":
                key = act["key"]
                value = act["value"]
                view = get_view(conn)
                existed = key in view
                inserted = False
                if mode == "ignore":
                    if not existed:
                        view[key] = value
                        inserted = True
                        ch = 1
                    else:
                        ch = 0
                elif mode == "replace":
                    view[key] = value
                    inserted = True
                    ch = 1
                elif mode == "upsert":
                    if existed:
                        view[key] = value
                        ch = 1
                        inserted = False
                    else:
                        view[key] = value
                        inserted = True
                        ch = 1
                # update changes() for this connection
                if conn == "main":
                    changes_main = ch
                    total_main += ch
                    if trig and inserted:
                        total_main += 1
                else:
                    total_other += ch
                    if trig and inserted:
                        total_other += 1
            elif op == "update":
                key = act["key"]
                value = act["value"]
                view = get_view(conn)
                if key in view:
                    view[key] = value
                    ch = 1
                else:
                    ch = 0
                if conn == "main":
                    changes_main = ch
                    total_main += ch
                else:
                    total_other += ch
            elif op == "delete":
                key = act["key"]
                view = get_view(conn)
                if key in view:
                    del view[key]
                    ch = 1
                else:
                    ch = 0
                if conn == "main":
                    changes_main = ch
                    total_main += ch
                else:
                    total_other += ch

        # After all actions, committed state is in committed (pending not committed)
        # But if a transaction is open at end, committed state is the committed dict.
        # The separate read connection sees committed state.
        count = len(committed)
        total_sum = sum(committed.values())

        if chan == "changes":
            channel = changes_main
        elif chan == "total":
            channel = total_main
        else:  # total_both
            channel = total_main + total_other

        return channel, count, total_sum

    # Filter candidates
    modes = ["ignore", "replace", "upsert"]
    chans = ["changes", "total", "total_both"]
    trigs = [False, True]

    candidates = []
    for mode in modes:
        for chan in chans:
            for trig in trigs:
                ok = True
                for r in receipts:
                    ch, cnt, sm = simulate(mode, chan, trig, r["actions"])
                    obs = r["observed"]
                    if ch != obs["channel"] or cnt != obs["committed_count"] or sm != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((mode, chan, trig))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])

    results = set()
    for mode, chan, trig in candidates:
        ch, cnt, sm = simulate(mode, chan, trig, actions)
        if goal == "channel":
            results.add(ch)
        elif goal == "committed_count":
            results.add(cnt)
        elif goal == "committed_sum":
            results.add(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
